def best_intel_leaf(cases,algs):
    ranked=[]
    for spec in algs:
        family=spec.get('family'); depth=int(spec.get('max_depth',99))
        if family=='CART_AXIS':
            model=fit_tree(cases,int(spec.get('max_depth',4))); score=tree_acc(model,cases)
        elif family=='LINEAR_SCORE_SEARCH':
            model=fit_linear(cases); score=linear_acc(model,cases) if model else 0.0
        else:continue
        ranked.append((score,-depth,family=='CART_AXIS',dict(spec),model))
    if not ranked:return None,{'score':0.0}
    score,_,_,spec,model=max(ranked,key=lambda z:(z[0],z[1],z[2]))
    return {'op':'LEAF','algorithm':spec,'model':model},{'score':score}

fit_linear.source:
def fit_linear(cases):
    if not cases:return None
    keys=sorted({k for x,_ in cases for k in x})
    labels=sorted({y for _,y in cases},key=str)
    if len(labels)!=2:return None
    best=None
    for weights in itertools.product((-1.0,0.0,1.0),repeat=len(keys)):
        if not any(weights):continue
        vals=[sum(w*float(x.get(k,0.0)) for w,k in zip(weights,keys)) for x,_ in cases]
        unique=sorted(set(vals))
        thresholds=[(a+b)/2 for a,b in zip(unique,unique[1:])] or [0.0]
        for th in thresholds:
            for orient in (1,-1):
                preds=[labels[1] if orient*v>orient*th else labels[0] for v in vals]
                acc=sum(p==y for p,(_,y) in zip(preds,cases))/len(cases)
                cand=(acc,-sum(abs(w) for w in weights),tuple(weights),-abs(th),orient,th)
                model={'kind':'LINEAR_SCORE','features':keys,'weights':list(weights),'threshold':th,
                       'orientation':orient,'low_label':labels[0],'high_label':labels[1]}
                if best is None or cand>best[0]:best=(cand,model)
    return None if best is None else best[1]

fit_tree.source:
def fit_tree(cases,max_depth=4):
    data=[(dict(x),y) for x,y in cases]
    def build(rows,depth):
        ys=[y for _,y in rows]
        if not rows:return {'label':False}
        if len(set(map(str,ys)))==1:return {'label':ys[0]}
        if depth>=max_depth:return {'label':_majority(ys)}
        keys=sorted({k for x,_ in rows for k in x});parent=_gini(ys);best=None
        for key in keys:
            vals=[]
            for x,_ in rows:
                raw=x.get(key,0)
                vals.append(float(bool(raw)) if isinstance(raw,bool) else float(raw if raw is not None else 0.0))
            thresholds=_thresholds(vals)
            if not thresholds and set(vals)<=set([0.0,1.0]):thresholds=[0.5]
            for threshold in thresholds:
                left=[r for r,v in zip(rows,vals) if v<=threshold];right=[r for r,v in zip(rows,vals) if v>threshold]
                if not left or not right:continue
                impurity=(len(left)*_gini([y for _,y in left])+len(right)*_gini([y for _,y in right]))/len(rows)
                candidate=(parent-impurity,-len(left)*len(right),key,-threshold,left,right,threshold)
                if best is None or candidate[:4]>best[:4]:best=candidate
        if best is None:return {'label':_majority(ys)}
        _,_,key,_,left,right,threshold=best
        return {'feature':key,'threshold':threshold,'left':build(left,depth+1),'right':build(right,depth+1)}
    return build(data,0)

linear_acc.source:
def linear_acc(model,cases):
    if not model or not cases:return 0.0
    return sum(linear_predict(model,x)==y for x,y in cases)/len(cases)

tree_acc.source:
def tree_acc(tree,cases)->float:
    if not cases:return 0.0
    return sum(tree_predict(tree,x)==y for x,y in cases)/len(cases)
